<script setup lang="ts">
import { useApi } from '../../api/client'
import { apiError } from '../../utils/apiError'
import { formatChangeReport, relativeTime } from '../../utils/site'
const api = useApi(); const page = ref(1); const size = 20
const { data, error, status } = await useAsyncData('crawls', async () => { const r = await api.GET('/crawls', { params: { query: { offset: (page.value - 1) * size, limit: size } } }); if (!r.data) throw new Error(apiError(r.error)); return r.data }, { watch: [page] })
</script>
<template><div><PageHeader title="Crawls" description="History of site checks." /><UAlert v-if="error" color="error" :description="error.message" /><p v-else-if="status === 'pending' || !data">Loading crawls…</p><p v-else-if="!data.items.length">No crawls yet.</p><table v-else class="w-full text-left text-sm"><thead><tr><th scope="col">Site</th><th scope="col">Check</th><th scope="col">Trigger</th><th scope="col">Changes</th><th scope="col">Status</th></tr></thead><tbody><tr v-for="crawl in data.items" :key="crawl.id" class="border-t border-default"><td class="py-3"><NuxtLink v-if="crawl.site_id" class="text-primary" :to="`/sites/${crawl.site_id}`">{{ crawl.request.sites.map(s => s.name || s.domain).join(', ') }}</NuxtLink><span v-else>{{ crawl.request.sites.map(s => s.name || s.domain).join(', ') }}</span></td><td><NuxtLink class="text-primary" :to="`/crawls/${crawl.id}`">{{ relativeTime(crawl.created_at) }}</NuxtLink></td><td><UBadge color="neutral">{{ crawl.trigger }}</UBadge></td><td>{{ formatChangeReport(crawl.counters) }}</td><td><StatusBadge :status="crawl.status" /></td></tr></tbody></table><UPagination v-if="data && data.total > size" v-model:page="page" :items-per-page="size" :total="data.total" /></div></template>
